const sample = {
  "demo": true,
  "firstName": "Ibrahim",
  "email": "ibrahim@fieldnote.example",
  "phone": "+15555550123",
  "company": "Fieldnote",
  "source": "whatsapp",
  "receivedAt": "2026-11-25T08:00:00.000Z"
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const received = Date.parse(item.receivedAt || new Date().toISOString());
const ageSeconds = Math.max(0, Math.round((Date.now() - received) / 1000));
const withinWindow = ageSeconds <= 3 * 60;
const owners = ['Maya', 'Omar'];
const bucket = Math.abs(hash(String(item.email || item.phone || 'lead'))) % owners.length;
const owner = item.owner || owners[bucket];
const first = item.firstName || 'there';
const company = item.company || 'your team';
const message = withinWindow
  ? 'Hi ' + first + ', this is ' + owner + ' at Northwind. I just saw the ' + (item.source || 'request') + ' from ' + company + ' and can reply right now.'
  : 'Hi ' + first + ', this is ' + owner + '. Sorry we missed the first minute. I can still help ' + company + ' today.';
const record = {
  to: item.phone || '',
  email: item.email || '',
  from: '+15555550100',
  owner,
  message,
  subject: 'Re: ' + (item.source || 'your request'),
  body: message,
  ageSeconds,
  withinWindow,
  channel: 'whatsapp',
};
return {
  summary: (withinWindow ? 'Inside' : 'Outside') + ' the 3-minute window. ' + owner + ' owns the whatsapp reply.',
  route: withinWindow ? 'instant' : 'late',
  record,
  slackText: owner + ' should answer ' + (item.email || item.phone) + ' (' + ageSeconds + 's old).',
  actions: [{ app: 'whatsapp', operation: 'send', payload: record }],
};
function hash(value) {
  let h = 0;
  for (let i = 0; i < value.length; i++) h = (h * 31 + value.charCodeAt(i)) >>> 0;
  return h;
}

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'whatsapp-first-response',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
